# cases whose stdout carries Godot editor/ANSI blocks (frozen exception)
ANSI_CASES = ('export_preset_missing', 'export_readiness')

# designed-verb ERROR lines (mutant receipts) not carried by expected_errors
DESIGNED_ERRORS = ('ERROR: Invalid export preset name: Missing preset.', 'ERROR: LEVEL ASSERTION FAILED: loaded level cell lacks collision geometry', 'ERROR: chain incomplete collections=1 scene=SceneB:<Node#28655486425> old_alive=false')

# single-PASS rows whose PASS line carries no signature fragment (declared)
PASS_EXCEPTIONS = {'save_process_missing': 'PASS line carries no signature fragment; negative-assertion row'}

# structured-evidence fields that let a probe_* row stand in for stdout
STRUCTURED_EVIDENCE_FIELDS = ('arms', 'artifact', 'bound_seconds', 'bounded_claim', 'census', 'clean_classification', 'crash_allowlist', 'detached_control_case', 'detached_control_descendant_pid', 'discriminations', 'forged_release_case', 'forged_release_descendant_pid', 'gated_genuine_reps', 'gated_release_reps', 'genuine_control', 'hold_arm', 'hold_output_lines', 'injected_classification', 'injected_line', 'injected_output', 'inner_classifications', 'midline_spliced_line', 'mode', 'negative_assertion', 'pids', 'poll_tick_seconds', 'positive_assertion', 'provenance_only_line_diff', 'raw_output', 'release_arm', 'same_line_prefix_classification', 'same_line_prefix_output', 'same_line_spoof_classification', 'same_line_spoof_output', 'same_line_suffix_classification', 'same_line_suffix_output', 'seam_split_run', 'self_sigkill_exit', 'shape_matrix', 'sigabrt_exit', 'split_genuine', 'split_release')

FRAME_RE = re.compile(r"^\s+\[\d+\] ")
BACKTRACE_HEADS = ("   at: ", "   GDScript backtrace")


def _frags(sig):
    if sig is None:
        return []
    if isinstance(sig, (list, tuple)):
        return [str(x) for x in sig]
    return [str(sig)]


def _malformed(row):
    if not isinstance(row, dict):
        return "record-not-a-dict"
    for key in ("case", "verdict"):
        if not isinstance(row.get(key), str) or not row.get(key):
            return "missing-%s" % key
    if "output" not in row:
        if (row["case"].startswith("probe_")
                and any(f in row for f in STRUCTURED_EVIDENCE_FIELDS)):
            return "structured-evidence-row"  # declared non-stdout receipt class
        return "missing-output-key"
    out = row["output"]
    if out is None:
        return "output-is-none"
    if not isinstance(out, list):
        return "output-not-a-list"
    for line in out:
        if not isinstance(line, str):
            return "output-line-not-str"
    return None


def _pass_account(row, line, seen):
    """Declared-PASS test: byte-exact multiset census, or a pin fragment."""
    case = row["case"]
    census = MULTI_PASS_CENSUS.get(case)
    if census is not None:
        return seen.get(line, 0) <= census.count(line)
    if case in PASS_EXCEPTIONS:
        return True
    return any(f in line for f in _frags(row.get("signature")))


def _line_accounted(row, line, banner_idx):
    """V-rec account for one non-PASS line."""
    if line == "":
        return True
    if line == BANNER:
        return len(banner_idx) == 1 and banner_idx[0] == 0
    if line.startswith("ERROR: "):
        if any(line == e or line.startswith(e)
               for e in (row.get("expected_errors") or [])):
            return True
        return any(line.startswith(p) for p in DESIGNED_ERRORS)
    if line.startswith(BACKTRACE_HEADS) or FRAME_RE.match(line):
        return True
    if row["case"] in ANSI_CASES:
        return True
    return line.split(" ")[0] in CASE_VERBS.get(row["case"], ())


def receipt_shape_gate(rows):
    """V-rec v2: whole-stdout account + declared PASS account + fail-closed."""
    flags = []
    for i, row in enumerate(rows):
        bad = _malformed(row)
        if bad and bad != "structured-evidence-row":
            flags.append({"case": (row.get("case") if isinstance(row, dict)
                                    else "#%d" % i),
                           "reason": "malformed-record", "detail": bad})
            continue
        if bad == "structured-evidence-row":
            continue
        out = row["output"]
        n_pass = sum(1 for l in out if l.startswith("PASS"))
        expected_n = PASS_COUNT_EXPECTED.get(row["case"], 1)
        if n_pass != expected_n:
            flags.append({"case": row["case"], "reason": "pass-count-mismatch",
                           "detail": "n=%d expected=%d" % (n_pass, expected_n)})
        banner_idx = [j for j, l in enumerate(out) if l == BANNER]
        seen = {}
        for j, line in enumerate(out):
            if line.startswith("PASS"):
                seen[line] = seen.get(line, 0) + 1
                if not _pass_account(row, line, seen):
                    flags.append({"case": row["case"],
                                   "reason": "pass-line-unaccounted",
                                   "detail": "idx=%d %r" % (j, line[:160])})
                continue
            if not _line_accounted(row, line, banner_idx):
                flags.append({"case": row["case"], "reason": "unaccounted-line",
                               "detail": "idx=%d %r" % (j, line[:160])})
    return flags


def v_min_span_gate(rows):
    """V-min: spec wording read minimally (PASS account + span-foreign only)."""
    allow = set(MULTI_PASS_CENSUS)
    flags = []
    for i, row in enumerate(rows):
        bad = _malformed(row)
        if bad == "structured-evidence-row":
            continue
        if bad:
            flags.append({"case": (row.get("case") if isinstance(row, dict)
                                    else "#%d" % i),
                           "reason": "malformed-record", "detail": bad})
            continue
        out = row["output"]
        frags = _frags(row.get("signature"))
        pin_idx = [j for j, l in enumerate(out) if any(f in l for f in frags)]
        for j, line in enumerate(out):
            if line.startswith("PASS"):
                if row["case"] not in allow and not any(f in line for f in frags):
                    flags.append({"case": row["case"],
                                   "reason": "pass-line-unaccounted",
                                   "detail": "idx=%d %r" % (j, line[:160])})
                continue
            if pin_idx and pin_idx[0] < j < pin_idx[-1]:
                flags.append({"case": row["case"], "reason": "span-foreign-line",
                               "detail": "idx=%d %r" % (j, line[:160])})
    return flags


def _main(argv):
    import json as _json
    fn = v_min_span_gate if "--min" in argv else receipt_shape_gate
    payload = _json.loads(sys.stdin.read())
    rows = payload["results"] if isinstance(payload, dict) else payload
    print(_json.dumps(fn(rows), indent=1))
    return 0


if __name__ == "__main__":
    sys.exit(_main(sys.argv[1:]))
